"""Render manually authored semantic determinations against a structural denominator.

This does not inspect Ruby bodies or infer correctness. Every below fact was
authored after the logged range readings. It writes only audit artifacts here.
"""
import json
from pathlib import Path

OUT = Path(__file__).resolve().parent
units = json.loads((OUT/'structural-inventory.json').read_text())
notes = {}

def n(ids, clause, fact, boundary, status='LOCAL_MATCH'):
    for unit_id in ids.split():
        if unit_id in notes:
            raise ValueError(unit_id)
        notes[unit_id] = dict(formal_clause=clause, fact=fact, boundary=boundary, status=status)

